import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"恢复工作流（WinRE 风格）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/recovery.md","filePath":"zh/manual/recovery.md"}'),n={name:"zh/manual/recovery.md"};function l(c,e,d,i,r,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="恢复工作流-winre-风格" tabindex="-1">恢复工作流（WinRE 风格） <a class="header-anchor" href="#恢复工作流-winre-风格" aria-label="Permalink to &quot;恢复工作流（WinRE 风格）&quot;">​</a></h1><p>Open Cube OS <em>就是</em>恢复环境。Windows 将 WinRE 隐藏在启动故障之后，而这里的 <code>oc&gt;</code> Shell 是主要接口——并且它同时也是运行所在机器的救援工具包。</p><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><ul><li>即使<strong>完全没有磁盘</strong>，系统也能启动到 Shell（ISO 是自包含的）。</li><li>任何诊断都只需一条 Shell 命令——无需构建单独的救援介质，无需进入特殊模式。</li><li>崩溃产物会持久化到 /etc 卷，因此经历 panic 后重启的机器仍携带自己的证据。</li></ul><h2 id="崩溃产物" tabindex="-1">崩溃产物 <a class="header-anchor" href="#崩溃产物" aria-label="Permalink to &quot;崩溃产物&quot;">​</a></h2><p>当内核发生 panic（受保护自测之外未处理的异常）时：</p><ol><li>异常帧（寄存器、故障地址）转储到串口——你可以通过 <code>-serial file:log.txt</code> 查看。</li><li>一条崩溃日志条目被写入 /etc 卷。</li><li>机器停止运行（或根据看门狗策略重启）。</li></ol><p>重启后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dumpinfo            (inspect the saved crash dump)</span></span>
<span class="line"><span>oc&gt; dmesg               (kernel ring buffer from the current boot)</span></span>
<span class="line"><span>oc&gt; logcat              (follow the persistent kernel log live)</span></span>
<span class="line"><span>oc&gt; ls /etc             (crashlog files live here)</span></span></code></pre></div><h2 id="强制崩溃-以测试该流程" tabindex="-1">强制崩溃（以测试该流程） <a class="header-anchor" href="#强制崩溃-以测试该流程" aria-label="Permalink to &quot;强制崩溃（以测试该流程）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; crashtest           (deliberate kernel panic - safe on a scratch</span></span>
<span class="line"><span>                          system, everything not on /etc is lost)</span></span></code></pre></div><p><code>crashtest</code> 完整验证了转储路径：panic → 串口转储 → /etc 崩溃日志 → <code>dumpinfo</code> 读取回来。</p><h2 id="救援工具包" tabindex="-1">救援工具包 <a class="header-anchor" href="#救援工具包" aria-label="Permalink to &quot;救援工具包&quot;">​</a></h2><p>典型救援场景及其对应命令：</p><table tabindex="0"><thead><tr><th>场景</th><th>操作</th></tr></thead><tbody><tr><td>系统启动，然后行为异常</td><td><code>dmesg</code>、<code>logcat</code>、<code>health</code>、<code>health export</code> 获取 JSON 快照</td></tr><tr><td>用户程序挂起</td><td>通过进程命令列出任务并终止；<code>watchdog</code> 策略会终止饿死进程</td></tr><tr><td>磁盘可疑</td><td><code>dskstat</code>、<code>fsck &lt;dev&gt;</code>、以只读方式挂载检查</td></tr><tr><td>启动标志指向错误槽位</td><td>GRUB 菜单 → 强制使用另一个槽位；然后执行 <code>update rollback</code></td></tr><tr><td>网络配置丢失</td><td><code>config restore</code>（恢复默认）然后重新运行 <code>dhcp</code></td></tr><tr><td>日志溢出</td><td><code>logctl</code>（级别 + 过滤器），轮转是自动的（<code>kernel.log</code> → <code>kernel.log.1</code>）</td></tr></tbody></table><h2 id="看门狗-硬件层面" tabindex="-1">看门狗（硬件层面） <a class="header-anchor" href="#看门狗-硬件层面" aria-label="Permalink to &quot;看门狗（硬件层面）&quot;">​</a></h2><p><code>kernel/core/core_watchdog.c</code> 会启用真实硬件看门狗（如果平台有的话）：</p><ul><li><strong>Intel TCO</strong>（LPC 总线）：在 QEMU q35 上动态发现——端到端测试套件显示 <code>Intel TCO found: PMBASE=0x600 TCOBASE=0x660</code>，启用它、使其饥饿，机器确实硬重启并再次启动。</li><li><strong>ACPI WDAT</strong>：表项被编程；启用和重置以相同方式验证。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; watchdog            (status: hardware support + monitored slots)</span></span>
<span class="line"><span>oc&gt; watchdog feed       (feed the active watchdog)</span></span>
<span class="line"><span>oc&gt; watchdog start/stop/timeout ...   (see the command page)</span></span></code></pre></div><p>被监控的槽位额外实现了<em>策略</em>看门狗：必须定期为其槽位&quot;喂食&quot;的任务会被终止（原因记录在日志中），而不会导致内核崩溃——内核存活，违规进程不存活。</p><h2 id="健康监控" tabindex="-1">健康监控 <a class="header-anchor" href="#健康监控" aria-label="Permalink to &quot;健康监控&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; health              (CPU / memory / tasks / IO at a glance)</span></span>
<span class="line"><span>oc&gt; health watch        (live monitor, 1 s refresh)</span></span>
<span class="line"><span>oc&gt; health export       (JSON snapshot to /var/log/health.json)</span></span></code></pre></div><p>阈值会向内核日志发出警报（当某个循环程序锁定核心时显示 <code>CPU-LOCKED</code>、内存压力、IO 阻塞）——这些警报行正是端到端测试套件断言的内容。</p><p>（本段含 4 个 ⟪OC-…⟫ 占位标记，必须全部原样保留在原位置。）</p>`,24)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
